theorem ProbabilityTheory.extracted_1.{u_10, u_9, u_8} {Ω : Type u_8} {Ω₀ : Type u_9} {S : Type u_10}
  [inst : MeasurableSpace Ω] [inst_1 : MeasurableSpace Ω₀] [inst_2 : MeasurableSpace S]
  [inst_3 : MeasurableSingletonClass S] [hS : Nonempty S] {μ : Measure Ω} {μ₀ : Measure Ω₀} {X₀ : Ω₀ → S}
  [inst_4 : FiniteRange X₀] {X : Ω → S} (hX : Measurable X) (hi : IdentDistrib X₀ X μ₀ μ) :
  let A := FiniteRange.toFinset X₀;
  let X' := fun ω => if X ω ∈ A then X ω else hS.some;
  Measurable X' := by
  exact Measurable.ite (MeasurableSet.preimage (Finset.measurableSet A) hX) hX measurable_const
